'use strict';

// Arduino firmware template
// Motor driver assumed: L298N (or compatible dual H-bridge)
//
// Wiring (can be changed by editing the #define block):
//   ENA → D3  (left  motor speed, PWM)
//   IN1 → D2  (left  motor forward)
//   IN2 → D4  (left  motor backward)
//   IN3 → D5  (right motor forward)
//   IN4 → D7  (right motor backward)
//   ENB → D6  (right motor speed, PWM)
const TEMPLATE = `\
// ============================================================
// Generated by Car Block Coding
// Edit the pin #defines below to match your wiring.
// ============================================================
#include <Arduino.h>

// ── Motor driver pins (L298N) ────────────────────────────────
#define ENA 3   // Left  motor speed (PWM)
#define IN1 2   // Left  motor forward
#define IN2 4   // Left  motor backward
#define IN3 5   // Right motor forward
#define IN4 7   // Right motor backward
#define ENB 6   // Right motor speed (PWM)
#define LED_PIN 8 // Countdown LED

// ── Turn timing (milliseconds) ───────────────────────────────
// Tune these so 90° and 180° are accurate on your car.
#define TURN_90_MS  2500
#define TURN_180_MS 6000

// ── Internal state ───────────────────────────────────────────
static int motorSpeed = 128; // 0–255; set by setSpeed()

// ── Helper functions ─────────────────────────────────────────
void stopMotors() {
  digitalWrite(IN1, LOW); digitalWrite(IN2, LOW);
  digitalWrite(IN3, LOW); digitalWrite(IN4, LOW);
}

void setSpeed(int level) {
  if      (level == 1) motorSpeed = 64;
  else if (level == 2) motorSpeed = 128;
  else                 motorSpeed = 255;
  analogWrite(ENA, motorSpeed);
  analogWrite(ENB, motorSpeed);
}

void moveForward(int ms) {
  analogWrite(ENA, motorSpeed); analogWrite(ENB, motorSpeed);
  digitalWrite(IN1, LOW);  digitalWrite(IN2, HIGH);
  digitalWrite(IN3, HIGH); digitalWrite(IN4, LOW);
  delay(ms);
  stopMotors();
}

void moveBackward(int ms) {
  analogWrite(ENA, motorSpeed); analogWrite(ENB, motorSpeed);
  digitalWrite(IN1, HIGH); digitalWrite(IN2, LOW);
  digitalWrite(IN3, LOW);  digitalWrite(IN4, HIGH);
  delay(ms);
  stopMotors();
}

void turnLeft(int ms) {
  int savedSpeed = motorSpeed;
  motorSpeed = 255;
  analogWrite(ENA, 255); analogWrite(ENB, 255);
  digitalWrite(IN1, LOW);  digitalWrite(IN2, HIGH); // left  backward
  digitalWrite(IN3, LOW);  digitalWrite(IN4, HIGH); // right forward
  delay(ms);
  stopMotors();
  motorSpeed = savedSpeed;
  analogWrite(ENA, motorSpeed); analogWrite(ENB, motorSpeed);
}

void turnRight(int ms) {
  int savedSpeed = motorSpeed;
  motorSpeed = 255;
  analogWrite(ENA, 255); analogWrite(ENB, 255);
  digitalWrite(IN1, HIGH); digitalWrite(IN2, LOW);  // left  forward
  digitalWrite(IN3, HIGH); digitalWrite(IN4, LOW);  // right backward
  delay(ms);
  stopMotors();
  motorSpeed = savedSpeed;
  analogWrite(ENA, motorSpeed); analogWrite(ENB, motorSpeed);
}

// ── Arduino lifecycle ─────────────────────────────────────────
void setup() {
  pinMode(ENA, OUTPUT); pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT);
  pinMode(ENB, OUTPUT); pinMode(IN3, OUTPUT); pinMode(IN4, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  setSpeed(2);
  stopMotors();
  for (int i = 0; i < 10; i++) {
    digitalWrite(LED_PIN, HIGH);
    delay(200);
    digitalWrite(LED_PIN, LOW);
    delay(800);
  }
}

void loop() {
  // ── BEGIN GENERATED CODE ──────────────────────────────────
{{BODY}}
  // ── END GENERATED CODE ────────────────────────────────────

  // Program finished — stop forever
  stopMotors();
  while (true) {}
}
`;

// ── Instruction code generation ───────────────────────────────────────────────

function generateInstruction(node, indent) {
  indent = indent || '  ';
  switch (node.type) {
    case 'move_forward':
      return indent + `moveForward(${Math.round(node.duration * 1000)});`;

    case 'move_backward':
      return indent + `moveBackward(${Math.round(node.duration * 1000)});`;

    case 'turn_left':
      return indent + `turnLeft(TURN_90_MS);`;

    case 'turn_right':
      return indent + `turnRight(TURN_90_MS);`;

    case 'turn_around':
      return indent + `turnLeft(TURN_180_MS);`;

    case 'turn_left_for':
      return indent + `turnLeft(${Math.round(node.duration * 1000)});`;

    case 'turn_right_for':
      return indent + `turnRight(${Math.round(node.duration * 1000)});`;

    case 'wait':
      return indent + `delay(${Math.round(node.duration * 1000)});`;

    case 'set_speed':
      return indent + `setSpeed(${node.level});`;

    case 'repeat': {
      const inner = (node.body || []).map((n) => generateInstruction(n, indent + '  ')).join('\n');
      return indent + `for (int rep = 0; rep < ${node.times}; rep++) {\n` + inner + '\n' + indent + '}';
    }

    case 'loop_forever': {
      const inner = (node.body || []).map((n) => generateInstruction(n, indent + '  ')).join('\n');
      return indent + 'while (true) {\n' + inner + '\n' + indent + '}';
    }

    default:
      throw new Error(`Unknown instruction type: "${node.type}"`);
  }
}

// ── Public API ────────────────────────────────────────────────────────────────

function generate(ast) {
  if (!ast || ast.type !== 'program') {
    throw new Error('Invalid AST: expected { type: "program", body: [...] }');
  }
  if (!Array.isArray(ast.body) || ast.body.length === 0) {
    throw new Error('Program has no instructions.');
  }

  const lines = ast.body.map((node) => generateInstruction(node, '  '));
  return TEMPLATE.replace('{{BODY}}', lines.join('\n'));
}

module.exports = { generate };
